function groupOfClassList(classList) {
  for (const c of classList) {
    if (ALIASES[c]) return ALIASES[c];
  }
  for (const c of classList) {
    for (const [g, names] of Object.entries(GROUPS)) {
      if (names.includes(c)) return g;
    }
  }
  return null;
}

// ---------------------------------------------------------------- PART 1

function staticChecks() {
  const failures = [];
  const fail = (msg) => { failures.push(msg); console.log('FAIL: ' + msg); };

  const files = [];
  for (const root of STYLE_ROOTS) walk(path.join(ROOT, root), files);

  const canonical = new Set(CANONICAL_CSS.map((p) => path.join(ROOT, p)));

  // alias usage in PAGES (needed for the canonical-file rule)
  const aliasUsedInPage = new Map(); // alias -> page rel
  for (const page of PAGES) {
    const abs = path.join(ROOT, page);
    let html = '';
    try { html = fs.readFileSync(abs, 'utf8'); } catch { continue; }
    const attrs = classAttrsOf(html);
    for (const alias of Object.keys(ALIASES)) {
      if (!aliasUsedInPage.has(alias) && classWordIn(attrs, alias)) {
        aliasUsedInPage.set(alias, page);
      }
    }
  }

  for (const [alias, page] of aliasUsedInPage) {
    fail(`${page}: uses alias button class ${alias}; use the shared class ${GROUPS[ALIASES[alias]][0]} instead`);
  }

  for (const file of files) {
    const ext = path.extname(file).toLowerCase();
    let sources = []; // { label, text, isCanonical }
    if (ext === '.css') {
      let text = '';
      try { text = fs.readFileSync(file, 'utf8'); } catch { continue; }
      sources.push({ label: rel(file), text, isCanonical: canonical.has(file) });
    } else if (ext === '.html') {
      let html = '';
      try { html = fs.readFileSync(file, 'utf8'); } catch { continue; }
      const re = /<style\b[^>]*>([\s\S]*?)<\/style>/gi;
      let m;
      while ((m = re.exec(html))) {
        sources.push({ label: rel(file), text: m[1], isCanonical: false });
      }
    } else continue;

    for (const src of sources) {
      const css = stripComments(src.text);
      for (const rule of iterRules(css)) {
        for (const sel of splitSelectors(rule.selector)) {
          if (!isButtonStateSelector(sel)) continue;
          if (!src.isCanonical) {
            fail(`${src.label}: button state selector outside the shared definition: ${sel}`);
            continue;
          }
          for (const token of classTokensOfSelector(sel)) {
            if (ALIASES[token] && aliasUsedInPage.has(token)) {
              fail(`${src.label}: alias button class ${token} has its own state rule (second definition of ${ALIASES[token]}): ${sel}`);
              break;
            }
          }
        }
      }
    }
  }
  return failures;
}

// ---------------------------------------------------------------- PART 2

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.map': 'application/json',
  '.txt': 'text/plain; charset=utf-8',
};

function startServer() {
  const http = require('http');
  const server = http.createServer((req, res) => {
    try {
      let urlPath = decodeURIComponent((req.url || '/').split('?')[0]);
      if (urlPath.endsWith('/')) urlPath += 'index.html';
      const abs = path.resolve(ROOT, '.' + path.posix.normalize(urlPath));
      if (abs !== ROOT && !abs.startsWith(ROOT + path.sep)) {
        res.writeHead(403);
        res.end();
        return;
      }
      const data = fs.readFileSync(abs);
      res.writeHead(200, { 'Content-Type': MIME[path.extname(abs).toLowerCase()] || 'application/octet-stream' });
      res.end(data);
